const ViewLoadingFallback: React.FC = () => (
  <div className="flex min-h-[50vh] items-center justify-center" dir="rtl">
    <div className="flex items-center gap-2 rounded-2xl border border-nw-border bg-nw-surface px-4 py-3 text-xs font-bold text-nw-muted shadow-lg">
      <Loader2 className="h-4 w-4 animate-spin text-nw-info" />
      <span>جاري فتح الشاشة...</span>
    </div>
  </div>
);

export const App: React.FC = () => {
  const { activeTab, currentModal, themeMode } = useAppStoreSelector(
    (state) => ({
      activeTab: state.activeTab,
      currentModal: state.currentModal,
      themeMode: state.currentUser.themeMode,
    }),
    shallowEqual
  );
  const { setActiveTab } = useAppStoreActions();
  const {
    isAuthenticated,
    isLoading: isAuthLoading,
    recordSessionActivity,
  } = useAuthStore();
  const mainScrollRef = useRef<HTMLElement>(null);

  useEffect(() => {
    if (!isAuthenticated) return;

    const params = new URLSearchParams(window.location.search);
    if (params.get('screen') === 'orders') {
      setActiveTab('orders');
      params.delete('screen');
      params.delete('order');
      const query = params.toString();
      window.history.replaceState(
        null,
        '',
        `${window.location.pathname}${query ? `?${query}` : ''}${window.location.hash}`,
      );
    }
  }, [isAuthenticated, setActiveTab]);

  // Cheque notifications use the existing authenticated shell and page ACL.
  useEffect(() => {
    if (!isAuthenticated) return;
    const params = new URLSearchParams(window.location.search);
    if (params.get('screen') !== 'cheques') return;
    setActiveTab('cheques');
    params.delete('screen');
    const query = params.toString();
    window.history.replaceState(null, '', `${window.location.pathname}${query ? `?${query}` : ''}${window.location.hash}`);
  }, [isAuthenticated, setActiveTab]);

  useEffect(() => {
    if (mainScrollRef.current) {
      mainScrollRef.current.scrollTop = 0;
    }
    if (isAuthenticated) {
      recordSessionActivity();
    }
  }, [activeTab, isAuthenticated, recordSessionActivity]);

  useEffect(() => {
    const activeThemeMode = themeMode === 'light' ? 'light' : 'dark';
    const root = document.documentElement;

    root.dataset.theme = activeThemeMode;
    root.classList.toggle('theme-light', activeThemeMode === 'light');
    root.classList.toggle('theme-dark', activeThemeMode === 'dark');
    root.style.colorScheme = activeThemeMode;

    document
      .querySelector<HTMLMetaElement>('meta[name="theme-color"]')
      ?.setAttribute('content', activeThemeMode === 'light' ? '#f7f8fa' : '#020617');
  }, [themeMode]);

  const renderActiveTabContent = () => {
    switch (activeTab) {
      case 'home':
      case 'dashboard':
        return <DashboardView />;
      case 'orders':
        return <OrdersCenterView />;
      case 'sales_history':
        return <SalesHistoryView />;
      case 'pos':
        return <PosView />;
      case 'products':
        return <ProductsView />;
      case 'accounts':
        return <AccountsView />;
      case 'inventory':
        return <InventoryView />;
      case 'expenses':
        return <ExpensesView />;
      case 'shifts':
        return <ShiftsView />;
      case 'reports':
        return <ReportsCenterView />;
      case 'users':
        return <UsersView />;
      case 'purchases':
        return <DirectReceivingView />;
      case 'assistant':
        return <AdminAssistantView />;
      case 'more':
        return <MoreMenuView />;
      case 'go_live':
        return <GoLiveSetupView />;
      case 'cheques':
        return <ChequesView />;
      case 'warehouses':
        return <WarehousesView />;
      default:
        return <DashboardView />;
    }
  };

  // 1. Initial Session Check Screen
  if (isAuthLoading) {
    return (
      <IPhoneContainer>
        <div dir="rtl" className="min-h-full flex flex-col items-center justify-center p-6 text-nw-text space-y-4">
          <div className="w-16 h-16 rounded-2xl bg-nw-info-bg text-nw-info border border-nw-border flex items-center justify-center shadow-lg animate-pulse">
            <Building2 className="w-8 h-8" />
          </div>
          <div className="flex items-center gap-2.5 text-xs font-bold text-nw-muted bg-nw-surface border border-nw-border px-4 py-2 rounded-2xl shadow">
            <Loader2 className="w-4 h-4 animate-spin text-nw-info" />
            <span>جاري التحقق من جلسة الدخول والمصادقة...</span>
          </div>
        </div>
      </IPhoneContainer>
    );
  }

  // 2. Unauthenticated -> Login View Screen
  if (!isAuthenticated) {
    return (
      <IPhoneContainer>
        <LoginView />
      </IPhoneContainer>
    );
  }

  // 3. Authenticated -> Full Application Interface
  return (
    <IPhoneContainer>
      <NavigationShell>
      {/* Desktop: side navigation (POS collapses it to an icon rail). Phone: bottom tabs. */}
      <div className="flex h-full min-h-0 w-full">
      <SideNav collapsed={activeTab === 'pos'} />
      <div className="flex min-h-0 min-w-0 flex-1 flex-col">
      {/* Top Header Bar */}
      <Header />

      {/* Main Active View Scroll Area */}
      <main ref={mainScrollRef} className="flex-1 overflow-y-auto no-scrollbar">
        <AppErrorBoundary key={activeTab}>
          <Suspense fallback={<ViewLoadingFallback />}>
            {renderActiveTabContent()}
          </Suspense>
        </AppErrorBoundary>
      </main>

      {/* Phone-only bottom tabs with the centre "بيع"; desktop uses the SideNav. */}
      <div className="contents lg:hidden">
        <BottomTabs />
      </div>
      </div>
      </div>

      {/* All Modal Sheets Dispatcher */}
      {currentModal && (
        <Suspense fallback={null}>
          <AllModals />
        </Suspense>
      )}
      </NavigationShell>
    </IPhoneContainer>
  );
};

export default App;

